head.script:
// 테스트 설명, 유효성 값 설정
//  ★ 이 _4 샘플은 Body 가 MultiLine(한 데이터 Row 가 2 Line 으로 렌더)일 때
//     mergeCell 의 rowIndex / colIndex 인덱싱 동작만 검증한다. (분리 사유 validation 2개)
scwin.tData = {
    "description" : "[gridView > M > mergeCell]<br/>Body Cell 정보를 사용하여 Body 영역의 특정 Cell 을 병합합니다.",
    "validation" : [
        "Body 가 MultiLine 일때 각 Line 의 Row 인덱스값은 같습니다.",
        "Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 데이터 — 2개 데이터 Row. 각 데이터 Row 는 4개 컬럼값을 가지며 2 Line 으로 나뉘어 표시된다.
//          (Line1 : col1,col2 / Line2 : col3,col4). 모든 Cell 값이 서로 다름.
scwin.MERGE_DATA = [
    { "col1": "R0L1C0", "col2": "R0L1C1", "col3": "R0L2C0", "col4": "R0L2C1" },
    { "col1": "R1L1C0", "col2": "R1L1C1", "col3": "R1L2C0", "col4": "R1L2C1" }
];



// comp 생성 : Body 가 MultiLine 인 그리드 1개를 동적 생성한다.
//  ★ header / gBody 에 각각 w2:row 2개(Line1/Line2) → 한 데이터 Row 가 2 Line 으로 렌더(MultiLine).
//     mergeCell 은 메소드 호출이므로 dynamicCreate 후 par_ 입력 기반으로 호출한다.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="MultiLine 그리드. 데이터 Row 2개, 각 Row 가 2 Line 으로 렌더(Line1 col0,col1 / Line2 col2,col3). 같은 데이터 Row 의 Line1·Line2 Cell 은 동일 rowIndex, Line 이 달라도 Column 은 서로 다른 고유 colIndex 를 가짐"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    let cList = $c.gcm.createCList({ dataList: "data:" + dlt_bind.id });

    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:420px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCell MultiLine sample"></w2:caption>';
    // header : 2 Line (Line1 / Line2)
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcolumn1" value="Line1 col0"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcolumn2" value="Line1 col1"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcolumn3" value="Line2 col2"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcolumn4" value="Line2 col3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // gBody : 2 Line (Line1 / Line2) → 한 데이터 Row 가 2 Line 으로 렌더
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 공통 : 병합 시작(anchor) td 의 rowSpan/colSpan 과 표시값을 반환
//  - td id 형식 : target1_cell_{rowIndex}_{colIndex}
scwin.getAnchorSpan = function (rowIndex, colIndex) {
    let td = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + colIndex + "']");
    if (!td) return null;
    return { rowSpan: td.rowSpan || 1, colSpan: td.colSpan || 1, text: (td.textContent || '').trim() };
}



// MultiLine rowIndex/colIndex 검증 (버튼 1개) :
//  mergeCell({rowIndex:0, colIndex:2, colSpan:2}) 호출로 두 유효성을 함께 입증한다.
//   - rowIndex 0 : Line1·Line2 가 공유하는 데이터 Row (validation1)
//   - colIndex 2 : Line1(col0,col1)에 이어 Line2 의 첫 Column 에 연속 부여된 고유 colIndex (validation2)
//   → 병합 Cell 의 표시값이 Line2 값(R0L2*)이면, 데이터 Row 공유 rowIndex 와 Line2 고유 colIndex 가
//     동시에 맞아 떨어져 Line2 Cell 에 병합이 적용된 것 = 두 유효성 동시 입증.
scwin.btn_verify_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    target1.mergeCell({ "rowIndex": 0, "colIndex": 2, "colSpan": 2 });

    let anchor = scwin.getAnchorSpan(0, 2);
    if (anchor) {
        let appliedToLine2 = anchor.text.indexOf("L2") > -1;
        bottom.setReturnValue("rowIndex 0(Line 공유) + colIndex 2(Line2 고유) → Line2 Cell 에 병합 적용 : " + appliedToLine2 + " (표시값='" + anchor.text + "')");
    } else {
        bottom.setReturnValue("시작 Cell td 를 찾을 수 없습니다.");
    }
}
